<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><meta name="robots" content="noindex,nofollow,noarchive"><title>Security & Access - C-Net Library</title><style>*{box-sizing:border-box}body{font-family:Inter,Arial,sans-serif;background:#f4f7fa;margin:0;color:#172033}.wrap{max-width:1320px;margin:28px auto;padding:0 18px}.top{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:18px}.brand{font-size:12px;text-transform:uppercase;letter-spacing:1.3px;color:#0f766e;font-weight:800}.btn{display:inline-flex;align-items:center;justify-content:center;background:#102a43;color:#fff;border:1px solid #102a43;border-radius:9px;padding:9px 12px;cursor:pointer;text-decoration:none;font-weight:700}.btn.alt{background:#fff;color:#102a43;border-color:#ccd7e1}.btn.green{background:#0f766e;border-color:#0f766e}.muted{color:#718096}.stats{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin-bottom:18px}.stat,.card{background:#fff;border:1px solid #e1e8ef;border-radius:15px;padding:17px;box-shadow:0 6px 22px rgba(15,23,42,.035)}.stat strong{display:block;font-size:25px;color:#102a43}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.card{margin-bottom:16px}.formgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.wide{grid-column:1/-1}.field{margin:8px 0}.field label{display:block;font-size:12px;font-weight:800;color:#52677a;margin-bottom:5px;text-transform:uppercase}input[type=text],input[type=email],input[type=password],input[type=search],select{width:100%;padding:9px;border:1px solid #ccd7e1;border-radius:9px;background:#fff}.users{display:grid;gap:12px}.row{border:1px solid #e2e8f0;border-radius:12px;padding:13px}.filter{display:grid;grid-template-columns:2fr 1fr auto;gap:8px;margin-bottom:13px}.badge{display:inline-block;background:#e8f5f2;color:#0f766e;padding:4px 8px;border-radius:999px;font-size:11px;font-weight:800}.dangerNote{font-size:12px;color:#9a3412;background:#fff7ed;padding:8px;border-radius:8px;margin:8px 0}.okNote{font-size:12px;color:#166534;background:#f0fdf4;padding:8px;border-radius:8px;margin:8px 0}.tableWrap{overflow:auto}.table{width:100%;border-collapse:collapse;min-width:720px}.table th,.table td{padding:10px;border-bottom:1px solid #edf0f4;text-align:left;font-size:13px}.table th{font-size:11px;text-transform:uppercase;color:#64748b}.permGroups{display:grid;gap:13px;margin:14px 0}.permGroup{background:#f8fafc;border-radius:11px;padding:11px}.perm{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}@media(max-width:1000px){.stats{grid-template-columns:repeat(3,1fr)}.grid{grid-template-columns:1fr}}@media(max-width:620px){.stats{grid-template-columns:1fr 1fr}.filter,.formgrid{grid-template-columns:1fr}.wide{grid-column:auto}.top{align-items:flex-start;flex-direction:column}}</style></head><body><div class="wrap"><div class="top"><div><div class="brand">Administration</div><h1 style="margin:2px 0">Security, Roles & Backoffice Users</h1><div class="muted">Create branch staff logins, control branch scope and permissions, and review administrative activity.</div></div><a class="btn alt" href="{{ route('admin.dashboard') }}">Dashboard</a></div>
