<form method="POST" action="{{ route('admin.security.backoffice-users.update',$user) }}">@csrf @method('PATCH')<div class="formgrid"><div class="field"><label>Name</label><input type="text" name="name" value="{{ $user->name }}" required></div><div class="field"><label>Email</label><input type="email" name="email" value="{{ $user->email }}" required></div><div class="field"><label>Branch</label><select name="branch_id" required>@foreach($branches as $branch)<option value="{{ $branch->id }}" @selected((string)$user->branch_id===(string)$branch->id)>{{ $branch->name }}</option>@endforeach</select></div><div class="field"><label>Primary Role</label><select name="primary_role" required>@php($currentSlug=$user->roles->first()?->slug)@foreach($backofficeRoles as $role)<option value="{{ $role->slug }}" @selected($currentSlug===$role->slug)>{{ $role->name }}</option>@endforeach</select></div></div><label><input type="checkbox" name="status" value="1" @checked($user->status)> Active login</label><div style="margin-top:8px"><button class="btn" type="submit">Save User</button></div></form>
