<div class="card"><div class="top" style="margin-bottom:12px"><div><h2 style="margin:0">Recent Audit Trail</h2><div class="muted">Latest 100 matching administrative events.</div></div><form method="GET" style="display:flex;gap:7px"><input type="search" name="audit_search" value="{{ request('audit_search') }}" placeholder="Action, user, entity or IP"><button class="btn" type="submit">Search</button></form></div><div class="tableWrap"><table class="table"><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Entity</th><th>IP Address</th></tr></thead><tbody>@forelse($logs as $log)<tr><td>{{ $log->created_at?->format('d M Y H:i') }}</td><td>{{ $log->user?->name ?? 'System' }}@if($log->user?->email)<div class="muted">{{ $log->user->email }}</div>@endif</td><td><span class="badge">{{ $log->action }}</span></td><td>{{ $log->auditable_type ? class_basename($log->auditable_type).' #'.$log->auditable_id : '—' }}</td><td>{{ $log->ip_address ?: '—' }}</td></tr>@empty<tr><td colspan="5" class="muted">No matching audit activity.</td></tr>@endforelse</tbody></table></div></div></div></body></html>